entries.changeset.ts:inverse:
export function inverse(facts: readonly Fact[]): Fact[] {
    const out: Fact[] = [];
    for (let i = facts.length - 1; i >= 0; i--) {
        const [op, id, field, value] = facts[i]!;
        out.push([op === "+" ? "-" : "+", id, field, value]);
    }
    return out;
}

